const QUESTIONS = [
  {"id": "A01", "prompt": "Een nieuwe collega gaat voor het eerst met een heftruck rijden op jullie locatie. Wat moet de werkgever regelen voordat de collega zelfstandig aan de slag gaat?", "options": ["Een routekaart meegeven en de collega daarna zelfstandig laten oefenen.", "Zorgen voor passende instructie en nagaan of de collega deskundig genoeg is voor de truck en het werk.", "De collega een proefrit laten maken en de instructie na de eerste dienst plannen.", "Alleen controleren of de collega ooit een heftrucktraining heeft gevolgd."], "correct": [1], "feedback": "De werkgever zorgt voor doeltreffende voorlichting en instructie. Voor het bedienen van een mobiele machine zoals een heftruck is specifieke deskundigheid nodig. Een eerdere training kan daarbij helpen, maar zegt op zichzelf weinig over de lokale rijroutes, gevaren of een ander type truck.", "image": "law", "alt": "Illustratie van een boek over de Arbowet"},
  {"id": "A02", "prompt": "Je leidinggevende vraagt je een pallet op te halen in een zone waar veiligheidsschoenen zijn voorgeschreven. Wat is jouw taak als werknemer?", "options": ["Je gebruikt de schoenen alleen bij het op- en afstappen van de truck.", "Je laat de keuze afhangen van het gewicht van de pallet.", "Je gebruikt je gewone schoenen zolang je de truck niet verlaat.", "Je draagt de voorgeschreven schoenen en gebruikt ze zoals uitgelegd in de instructie."], "correct": [3], "feedback": "Artikel 11 van de Arbowet verplicht werknemers om de verstrekte persoonlijke beschermingsmiddelen op de juiste manier te gebruiken. Voor deze zone gelden de schoenen ook als je vooral rijdt. De werkgever moet passende bescherming verstrekken en uitleggen hoe je die gebruikt."},
  {"id": "A03", "prompt": "Bij de RI&E blijkt dat voetgangers en heftrucks vaak tegelijk dezelfde smalle doorgang gebruiken. Wat hoort in het plan van aanpak?", "options": ["Een plattegrond van de hal en een lijst van alle aanwezige heftrucks.", "Een overzicht van de medewerkers die al een heftruckopleiding hebben gevolgd.", "Een maatregel om het risico te verminderen, een verantwoordelijke en een termijn.", "Een aantekening dat iedereen alert moet blijven, zonder verdere afspraken."], "correct": [2], "feedback": "De RI&E brengt het risico in kaart. In het plan van aanpak staat wat het bedrijf gaat doen, wie het regelt en wanneer. Denk bij deze doorgang aan een gescheiden looproute of een andere inrichting die de kans op een aanrijding verlaagt.", "image": "traffic", "alt": "Gemarkeerde looproute in een bedrijfshal"},
  {"id": "A04", "prompt": "Na een aanrijding met een heftruck wordt een werknemer opgenomen in het ziekenhuis. Welke actie hoort bij de werkgever volgens de Arbowet?", "options": ["Het arbeidsongeval direct melden bij de Nederlandse Arbeidsinspectie.", "Het ongeval uitsluitend registreren tot de werknemer weer aan het werk gaat.", "De melding pas doen nadat het interne onderzoek is afgerond.", "De melding overlaten aan het ziekenhuis en zelf alleen de schade vastleggen."], "correct": [0], "feedback": "Bij overlijden, blijvend letsel of ziekenhuisopname moet de werkgever het arbeidsongeval direct melden bij de Nederlandse Arbeidsinspectie. Blijkt de ziekenhuisopname of het blijvend letsel pas later, dan meldt de werkgever zodra het bekend is. Interne registratie en onderzoek staan los van de directe melding."},
  {"id": "A05", "prompt": "Het bedrijf kan de looproute fysiek scheiden van de heftruckroute. Welke maatregel past bij de volgorde van de Arbowet als de routes naast elkaar moeten blijven?", "options": ["Iedereen een zichtbaarheidsvest geven en de indeling van de routes laten zoals die is.", "Een fysieke afscheiding aanbrengen en aanvullende instructies geven waar routes elkaar kruisen.", "Een bord ophangen met het verzoek om eerst oogcontact te maken.", "Het claxongebruik herhalen in het werkoverleg en verder vertrouwen op oplettendheid."], "correct": [1], "feedback": "Artikel 3 van de Arbowet geeft voorrang aan het wegnemen of beperken van risico’s bij de bron en vervolgens aan collectieve bescherming. Een fysieke scheiding beschermt iedereen op de looproute. Op de plekken waar verkeer elkaar nog kruist, kunnen aanvullende afspraken nodig zijn.", "image": "warehouse", "alt": "Magazijngangen met rijmarkering"},
  {"id": "K01", "prompt": "Je gaat een open vrachtwagen of een vrachtwagen met schuifzeilen laden of lossen. Welke vier controles horen direct bij deze taak?", "options": ["Controleer of het voertuig is geborgd tegen wegrollen.", "Controleer of de chauffeur de dagelijkse controle van zijn cabine heeft afgetekend.", "Controleer de staat, breedte, hoogte en vlakheid van de laadvloer en of de zeilen vrij zijn.", "Stem de werkwijze af en controleer of de chauffeur op de afgesproken veilige plaats staat.", "Controleer de route die de chauffeur na vertrek over de openbare weg rijdt.", "Controleer bij een afgekoppelde oplegger of de vereiste ondersteuning is aangebracht.", "Controleer het rijbewijs van de vrachtwagenchauffeur.", "Controleer hoeveel pauze de chauffeur onderweg heeft gehad."], "correct": [0, 2, 3, 5], "feedback": "Borging voorkomt dat de vrachtwagen zich verplaatst. De laadvloer en vrije toegang moeten passen bij de laad- of losmethode. Spreek af waar de chauffeur veilig wacht en controleer bij een afgekoppelde oplegger de ondersteuning volgens de locatieprocedure om kantelen te voorkomen."},
  {"id": "K02", "prompt": "Waarom neem je een geschikte palletlast tijdens vervoer zo dicht mogelijk tegen de hiel van de vorken op?", "options": ["De afstand van de hiel tot het zwaartepunt van de last blijft zo klein mogelijk.", "De barcode wordt daardoor altijd zichtbaar voor de scanner.", "De voorwaartse belasting van de truck blijft kleiner dan bij vervoer op de vorkpunten.", "Je krijgt daardoor altijd vrij zicht over de last.", "De last rust diep op de vorken en kan waar geschikt steun vinden tegen het vorkenbord of lastrek.", "De totale lengte van de combinatie truck en last blijft zo klein mogelijk.", "De maximale hefhoogte van de mast wordt groter.", "De noodzakelijke breedte tussen de vorken wordt automatisch kleiner."], "correct": [0, 2, 4, 5], "feedback": "De hiel is de binnenhoek waar het horizontale en verticale deel van de vork samenkomen. Dicht bij de hiel is de hefboom van de last kleiner, staat de last dieper op de vorken en steekt de combinatie minder ver uit. Controleer daarnaast de borging en de gegevens op het lastdiagram.", "image": "forkboard", "alt": "Vorkenbord met twee vorken"},
  {"id": "K03", "prompt": "Welke vier situaties vergroten vooral het gevaar dat een heftruck zijdelings kantelt?", "options": ["Met te hoge snelheid een bocht nemen.", "Rustig remmen op een rechte, vlakke route.", "Een last rijden waarvan de inhoud zijwaarts kan verschuiven of klotsen.", "Recht en langzaam over een toegestane helling rijden volgens de truckinstructie.", "Vóór een bocht snelheid minderen en de last in transportstand houden.", "Dwars over een helling rijden of op de helling een bocht maken.", "Een bocht maken terwijl de last hoog geheven is.", "De last gelijkmatig over de twee vorken verdelen."], "correct": [0, 2, 5, 6], "feedback": "In een bocht werken zijwaartse krachten op truck en last. Een hoge last en een dwarshelling verkleinen de stabiliteitsmarge. Een bewegende inhoud, zoals vloeistof in een deels gevulde tank, kan het zwaartepunt zijwaarts verplaatsen. Neem een toegestane helling recht en volg de instructie van de truck."},
  {"id": "K04", "prompt": "Op welke vier plaatsen laat je een heftruck niet geparkeerd achter?", "options": ["In een onoverzichtelijke bocht.", "Op een vlakke, aangewezen parkeerplaats.", "In een afgebakend parkeervak dat volledig buiten rij- en looproutes ligt.", "Op een helling.", "Op een aangewezen buitenparkeerplaats met stevige, vlakke ondergrond.", "Voor een nooduitgang.", "Op een plek waar de truck een gangpad blokkeert.", "Op een plek waar de truck volledig binnen het gemarkeerde parkeervak staat."], "correct": [0, 3, 5, 6], "feedback": "Kies een vlakke, aangewezen parkeerplek. Bij een blinde bocht is de truck te laat zichtbaar en op een helling kan hij wegrollen. Houd doorgangen, nooduitgangen en toegang tot hulp- en blusmiddelen vrij.", "image": "parking", "alt": "Aanduiding voor een heftruckparkeerplaats"},
  {"id": "K05", "prompt": "Welke vier ondergronden zijn ongeschikt voor een standaard magazijnheftruck?", "options": ["Een wegdek met diepe gaten en grote hoogteverschillen.", "Vlak, droog en voldoende draagkrachtig asfalt.", "Een glad wegdek met een oliefilm.", "Los grind waarop de wielen grip verliezen.", "Een vlakke, droge betonvloer die de truck en last kan dragen.", "Zachte grond waar de wielen in kunnen wegzakken.", "Een geschikte rijroute die vrij is van obstakels.", "Een stroeve, vlakke bedrijfsvloer die voor deze truck is vrijgegeven."], "correct": [0, 2, 3, 5], "feedback": "Gaten kunnen de truck laten schokken of doen overhellen. Olie en los materiaal verminderen de grip en zachte grond kan onder een wiel bezwijken. Controleer of de route voldoende draagkracht heeft voor de truck en de last samen."},
  {"id": "K06", "prompt": "Welke twee directe gevolgen kan een slechte ondergrond hebben voor het rijgedrag?", "options": ["De truck kan instabiel worden.", "De banden kunnen minder grip hebben.", "De waarde op het lastdiagram verandert vanzelf.", "De lastzwaartepuntafstand verandert altijd."], "correct": [0, 1], "feedback": "Een wiel kan in een kuil wegzakken, waardoor de truck scheef komt te staan. Bij te weinig grip kun je ook minder goed sturen en remmen. De gegevens op het lastdiagram blijven hetzelfde, maar die maken een slechte ondergrond niet geschikt.", "image": "ground", "alt": "Onvlak wegdek met kuilen"},
  {"id": "K07", "prompt": "De natte rijroute is volgens de locatie-instructie nog berijdbaar. Welke vier maatregelen helpen je de truck onder controle te houden?", "options": ["Pas de snelheid aan de grip aan.", "Schakel de verlichting uit om minder weerkaatsing te hebben.", "Claxonneer twee keer om de remweg te verkorten.", "Rem tijdig en gelijkmatig.", "Zet de mast bij elke last verplicht loodrecht tijdens het rijden.", "Maak de veiligheidsgordel los zodra je op het natte deel komt.", "Let op veranderingen in de ondergrond.", "Vermijd plotselinge of scherpe stuurbewegingen."], "correct": [0, 3, 6, 7], "feedback": "Op een natte vloer kunnen de banden grip verliezen en wordt de remweg langer. Met lagere snelheid en geleidelijke rem- en stuurbewegingen houd je meer controle. Blijf kijken naar plassen en andere veranderingen en onderbreek de rit als de route niet veilig berijdbaar is."},
  {"id": "K08", "prompt": "Welke vier handelingen vergroten direct het risico op voor- of achterover kantelen?", "options": ["Een combinatie van lastgewicht en lastzwaartepuntafstand heffen die buiten het lastdiagram valt.", "Met hooggeheven mast en last over de rijroute rijden.", "De controle vóór gebruik uitvoeren met de truck stil op een vlakke plek.", "Een geheven last te ver voorover neigen.", "Een vastgezette, stabiele last in de voorgeschreven transportstand rijden.", "Op een vlakke route met de voorgeschreven achterwaartse neiging rijden.", "Met een beladen truck op een helling rijden terwijl de last naar beneden wijst.", "Een passende last dichter bij de vorkhiel opnemen, binnen de capaciteit van de truck."], "correct": [0, 1, 3, 6], "feedback": "Bij overbelasting, voorover neigen op hoogte en een last aan de verkeerde kant van een helling schuift het gezamenlijke zwaartepunt richting de kantelgrens. Met een hooggeheven last kunnen remmen of oneffenheden extra veel invloed hebben. Rijd met de last laag en gebruik het lastdiagram voor de gemonteerde uitrusting.", "image": "mast", "alt": "Zijaanzicht van een hefmast"},
  {"id": "K09", "prompt": "Je moet controleren of een truck een last op de gewenste plek kan zetten. Welke drie gegevens gebruik je bij het lezen van het lastdiagram?", "options": ["De toegestane hefcapaciteit bij die combinatie.", "De modelnaam die op de zijkant van de truck staat.", "Het gewicht van de tractiebatterij als aparte invoer in het lastdiagram.", "De lastzwaartepuntafstand.", "Het serienummer van de truck als maat voor het hefvermogen.", "De benodigde hefhoogte."], "correct": [0, 3, 5], "feedback": "Zoek in het juiste lastdiagram de toegestane hefcapaciteit voor de benodigde hefhoogte en lastzwaartepuntafstand. Vergelijk deze waarde met het totale gewicht dat je werkelijk heft. Het serienummer helpt bij identificatie van de truck, maar is geen waarde die je in het diagram afleest."},
  {"id": "K10", "prompt": "Welke vier gegevens over een onbekende palletlast controleer je voordat je hem opneemt?", "options": ["Het totale gewicht.", "De ligging van het zwaartepunt van de last.", "Of de last dicht genoeg bij het kantoor staat om het label te lezen.", "De staat van de pallet en of de last stabiel en geborgd is.", "De naam van de leverancier als vervanging voor de gewichtscontrole.", "Het afleveradres als maat voor de stabiliteit.", "De samenstelling van de last, bijvoorbeeld of de inhoud kan verschuiven.", "De houdbaarheidsdatum als maat voor het hefvermogen."], "correct": [0, 1, 3, 6], "feedback": "Voor de capaciteit moet je gewicht en lastzwaartepuntafstand kennen. Controleer ook of de pallet heel is en de lading op haar plek blijft. Een deels gevulde vloeistofcontainer gedraagt zich bij remmen en sturen anders dan een gelijkmatig verdeelde, vaste last.", "image": "pallet", "alt": "Houten pallet met vorkopeningen"},
  {"id": "K11", "prompt": "Je stopt vlak voor een stapel voordat je de vorken heft. Welke twee voordelen heeft dit?", "options": ["Je kunt de vorken nauwkeurig op de opnamepunten richten.", "Je kunt het volgende deel van de handeling op hogere snelheid uitvoeren.", "De batterij verbruikt bij elke stop gegarandeerd minder energie.", "Je beperkt de ruimte waar iemand tussen de truck en de stapel kan doorlopen."], "correct": [0, 3], "feedback": "Dichtbij en recht voor de stapel kun je de vorken nauwkeurig op hoogte brengen. Een kleine tussenruimte verkleint de kans dat iemand erdoorheen loopt. Houd de werkzone vrij en wacht zodra iemand de zone betreedt."},
  {"id": "K12", "prompt": "Wat is het belangrijkste kantelgevaar als je dwars over een helling rijdt?", "options": ["De truck kan zijwaarts omslaan naar de lage kant.", "De truck kan alleen in de lengterichting kantelen."], "correct": [0], "feedback": "Op een dwarshelling helt de hele truck zijwaarts. Het gezamenlijke zwaartepunt kan daardoor de zijdelingse kantelgrens passeren. Gebruik een toegestane helling recht in de lengterichting en draai pas op een vlak gedeelte.", "image": "slope", "alt": "Schematische heftruck bij een helling"},
  {"id": "K13", "prompt": "Je nadert een hoek waar je kruisend verkeer pas laat ziet. Welke vier handelingen helpen direct bij het veilig passeren?", "options": ["Verminder je snelheid vóór de hoek.", "Controleer alleen of je veiligheidsschoenen nog goed vastzitten.", "Waarschuw met de claxon volgens de verkeersafspraken op locatie.", "Kies binnen je eigen rijruimte een lijn met het beste zicht op kruisend verkeer.", "Snijd de hoek af om de kruising sneller vrij te maken.", "Rijd voorzichtig en wees klaar om te stoppen.", "Rijd met hetzelfde tempo door zolang je verlichting aan is."], "correct": [0, 2, 3, 5], "feedback": "Snelheid minderen en voldoende zicht geven je tijd om te reageren. Een signaal kan anderen waarschuwen, maar geeft je geen voorrang. Blijf binnen de gemarkeerde rijroute en stop als je de doorgang niet veilig kunt overzien."},
  {"id": "K14", "prompt": "Je staat stil om een pallet af te zetten. Waarom gebruik je de parkeerrem en zet je de rijrichting in neutraal volgens de truckinstructie?", "options": ["De truck blijft op zijn plek tijdens de bediening van de hydrauliek.", "Je kunt daardoor veilig afstappen terwijl een last hoog geheven is.", "Je kunt je richten op het nauwkeurig afzetten zonder dat de truck onbedoeld gaat rijden.", "De handelingen maken een nieuwe omgevingscontrole vóór het wegrijden overbodig."], "correct": [0, 2], "feedback": "Parkeerrem en neutraal beperken onbedoelde rijbewegingen terwijl je de mast of vorken bedient. Daarmee houd je de positie ten opzichte van de stapel onder controle. Controleer de omgeving opnieuw voordat je gaat rijden.", "image": "controls", "alt": "Bedieningsplek in een heftruck"},
  {"id": "K15", "prompt": "Je vervoert een verplaatsbaar stapelframe met gemarkeerde vorkopnames. Welke twee instellingen kies je volgens de instructies van de truck en het frame?", "options": ["Spreid de vorken zo breed als de aangewezen vorkopnames toelaten.", "Rijd met dit frame altijd achteruit, ook als de route en het zicht vooruit vrij zijn.", "Laat een begeleider de keuze van vorkstand en mastneiging overnemen.", "Gebruik de voorgeschreven achterwaartse neiging voor het stabiel vervoeren van dit frame."], "correct": [0, 3], "feedback": "Een brede spreiding binnen de opnamepunten geeft het frame steun aan beide kanten. Gebruik de voor het frame en de truck voorgeschreven transportstand. De maximale achterwaartse neiging is alleen geschikt als de instructies die voor deze combinatie voorschrijven."},
  {"id": "K16", "prompt": "Je wilt meerdere beladen pallets zonder stelling op elkaar stapelen. Welke twee controles voer je vooraf uit?", "options": ["Controleer of de vloer vlak en draagkrachtig is en of de stapel geen route blokkeert.", "Controleer alleen of de opslag onder een dak ligt.", "Controleer of de lasten qua maat, gewicht en soort bij elkaar passen en gestapeld mogen worden.", "Controleer alleen of alle pallets van hout zijn."], "correct": [0, 2], "feedback": "De vloer moet het totale gewicht kunnen dragen en de stapel mag geen route blokkeren. De pallets, verpakkingen en inhoud moeten het gewicht erboven kunnen dragen. Volg de maximale stapelhoogte en stapelinstructies voor de betreffende lasten.", "image": "stack", "alt": "Opgeslagen pallets en opslagrekken"},
  {"id": "V01", "prompt": "Je neemt een heftruck over van de vorige ploeg. Wie voert de controle uit voordat jij ermee gaat rijden?", "options": ["De planner die de trucks over de ploegen verdeelt.", "De monteur die het periodieke onderhoud doet.", "Jij, als bestuurder die de truck in gebruik neemt.", "De verzekeraar van de werkgever."], "correct": [2], "feedback": "De bestuurder controleert de truck vóór gebruik volgens de checklist. Kijk onder meer naar de vorken en banden en test de bedienings- en veiligheidsfuncties volgens de instructie. De gebruikscontrole staat naast periodiek onderhoud en keuring."},
  {"id": "V02", "prompt": "Twee lasten wegen evenveel. Door welke verandering kan de toegestane hefcapaciteit kleiner worden?", "options": ["Het zwaartepunt van de last ligt verder van de vorkhiel.", "Het zwaartepunt van de last ligt dichter bij de vorkhiel.", "Het etiket op de last is vanaf de bestuurdersstoel onleesbaar.", "De route wordt bij hetzelfde lastzwaartepunt achteruit gereden."], "correct": [0], "feedback": "Een grotere lastzwaartepuntafstand geeft de last een langere hefboom. Daardoor kan het lastdiagram een lagere toegestane massa aangeven, ook als de last evenveel weegt. Lees de waarde voor de combinatie van afstand, hefhoogte en uitrusting.", "image": "loadplate", "alt": "Voorbeeld van een lastplaat op een heftruck"},
  {"id": "V03", "prompt": "Tijdens het manoeuvreren nadert een voetganger je werkzone. Wie moet de rijbeweging zo nodig stoppen?", "options": ["De heftruckbestuurder die de truck op dat moment bedient.", "De manager die het verkeersplan heeft goedgekeurd.", "De voetganger, door op het laatste moment een andere route te kiezen.", "De medewerker die de planning voor het magazijn maakt."], "correct": [0], "feedback": "Als bestuurder houd je zicht op de rijroute, uitzwaai en werkzone. Stop als iemand de gevarenzone nadert en ga verder wanneer de route vrij is. De werkgever en voetgangers hebben ook eigen taken bij de inrichting en het volgen van de verkeersafspraken."},
  {"id": "V04", "prompt": "Je zit goed, de gordel is om en de truck is klaar om te rijden. Welke controle doe je vlak vóór de truck in beweging komt?", "options": ["Je leest het lastdiagram opnieuw.", "Je kijkt alleen of de gekozen rijrichting op het display staat.", "Je kijkt rondom en controleert de richting waarin je vertrekt.", "Je geeft een geluidssignaal en vertrouwt erop dat iedereen aan de kant gaat."], "correct": [2], "feedback": "Een voetganger of voertuig kan sinds je laatste controle zijn verplaatst. Kijk rondom en controleer vooral de gekozen rijrichting vlak voordat je gaat rijden. Houd ook rekening met de ruimte die de achterkant van de truck nodig heeft.", "image": "driver", "alt": "Bestuurder in de beschermconstructie van de heftruck"},
  {"id": "V05", "prompt": "Welke situatie geeft op een vlakke vloer vooral gevaar voor zijdelings kantelen?", "options": ["Een beladen truck rijdt langzaam door een ruime bocht.", "Een beladen truck staat recht op een vlakke laadplek.", "Een lege truck rijdt rustig rechtuit met de vorken laag.", "Een lege truck maakt bij te hoge snelheid een scherpe bocht."], "correct": [3], "feedback": "Ook een onbeladen heftruck kan zijwaarts kantelen. Een scherpe bocht bij te hoge snelheid veroorzaakt grote zijwaartse krachten. Rem vóór de bocht af en stuur rustig, ook als de vorken leeg zijn."},
  {"id": "V06", "prompt": "Het lastdiagram vermeldt waarden voor een truck op een vlakke vloer. Welke maststand hoort bij de gebruikelijke referentie voor die waarden?", "options": ["De mast staat licht achterover.", "De hoek van de mast speelt geen rol.", "De mast staat licht voorover.", "De mast staat verticaal."], "correct": [3], "feedback": "Bij de gebruikelijke referentieconditie staat de mast verticaal en de truck vlak. Voorover neigen verplaatst een geheven last naar voren en vermindert de stabiliteitsmarge. Controleer altijd de voorwaarden bij het lastdiagram van jouw truck.", "image": "truck", "alt": "Contragewichtheftruck met mast en vorken"},
  {"id": "V07", "prompt": "Op een verzendlabel staan nettogewicht en brutogewicht. Wat is het verschil voor een verpakte last op een pallet?", "options": ["Netto is het product. Bruto omvat product, verpakking en pallet samen.", "Netto omvat product en pallet. Bruto is alleen het product.", "Netto en bruto zijn twee aanduidingen voor het gewicht van de truck.", "Bruto wordt alleen gebruikt bij een last met vloeistof."], "correct": [0], "feedback": "De truck draagt het product én alles wat je tegelijk optilt. Gebruik dus het volledige brutogewicht van de palletlast als dat alles omvat wat op de vorken komt. Controleer bij twijfel wat op het label is meegeteld."},
  {"id": "V08", "prompt": "Een zware machine staat uit het midden op een transportpallet. Welke maat bedoelen we met lastzwaartepuntafstand?", "options": ["De afstand tussen de linker- en rechtervork.", "De totale lengte van truck en lading samen.", "De afstand van het midden van de pallet tot de voorkant van de pallet.", "De horizontale afstand van de binnenzijde van de vorkhiel tot het werkelijke zwaartepunt van de last."], "correct": [3], "feedback": "Bij een ongelijk verdeelde last ligt het zwaartepunt niet noodzakelijk midden op de pallet. De afstand vanaf de hiel tot dat werkelijke zwaartepunt bepaalt mede het moment van de last. Gebruik die afstand samen met gewicht en hefhoogte om het lastdiagram te lezen.", "image": "heel", "alt": "Zijaanzicht van een vorkheftruck met een maatlijn bij de vorken"},
  {"id": "V09", "prompt": "Op een locatie geldt een interne schriftelijke rijtoestemming. Wie verleent die toestemming voor het werk op die locatie?", "options": ["De instructeur die de externe heftrucktraining gaf.", "De werkgever of de persoon die namens de werkgever bevoegd is.", "De leverancier die de truck heeft afgeleverd.", "De fabrikant die het lastdiagram heeft opgesteld."], "correct": [1], "feedback": "De werkgever bepaalt binnen de locatieafspraken wie welk type truck voor welke taken mag gebruiken. Een opleidingsbewijs kan helpen bij het aantonen van deskundigheid. Schriftelijke toestemming is in deze situatie een bedrijfsregel. Specifieke deskundigheid is vereist volgens het Arbobesluit."},
  {"id": "V10", "prompt": "Welke instantie houdt in Nederland toezicht op de naleving van de Arbowet op de werkvloer?", "options": ["De regionale omgevingsdienst.", "De branchevereniging voor intern transport.", "De Nederlandse Arbeidsinspectie.", "De examenorganisatie van de heftruckopleiding."], "correct": [2], "feedback": "De Nederlandse Arbeidsinspectie ziet toe op de naleving van arbeidsomstandighedenwetgeving. Zij kan een bedrijf inspecteren en bij overtredingen ingrijpen. Een opleider of brancheorganisatie kan informeren en opleiden, maar voert dit toezicht niet uit.", "image": "law", "alt": "Illustratie van een boek over de Arbowet"},
  {"id": "V11", "prompt": "Je ziet een nominale hefcapaciteit voor de referentiestand. Welke mastpositie past daarbij?", "options": ["De mast staat rechtop.", "De mast staat maximaal achterover.", "De mast staat voorover.", "De reachmast staat uitgeschoven en voorover."], "correct": [0], "feedback": "De nominale capaciteit geldt onder vastgelegde referentiecondities, waaronder de voorgeschreven maststand. Voor een concrete hefhandeling lees je het lastdiagram van de truck en de actuele configuratie. Bij grotere hefhoogte of lastzwaartepuntafstand kan de toegestane capaciteit lager zijn."},
  {"id": "V12", "prompt": "Hoe zet je de lege vorken van een heftruck met neigbare mast in de voorgeschreven transportstand op een vlakke rijroute?", "options": ["Hoog geheven en maximaal achterover.", "Laag en ver voorover, zodat de punten bijna over de vloer slepen.", "Laag met voldoende bodemvrijheid en iets achterover, volgens de truckinstructie.", "Ongeveer op kniehoogte en horizontaal, ongeacht de truck."], "correct": [2], "feedback": "Lage vorken beperken het gevaar van raken en helpen de stabiliteit te bewaren. Houd voldoende bodemvrijheid om te voorkomen dat de punten de vloer raken. Bij een truck met neigbare mast volg je de voorgeschreven achterwaartse neiging.", "image": "truck", "alt": "Contragewichtheftruck met mast en vorken"},
  {"id": "V13", "prompt": "De verkeersinstructie vraagt om een waarschuwingssignaal bij een blinde hoek. Hoe geef je in deze situatie het signaal?", "options": ["Met enkele korte, duidelijke signalen terwijl je langzaam nadert.", "Met één lang signaal en daarna op dezelfde snelheid doorrijden.", "Met een zo zacht mogelijk signaal om de accu te sparen.", "Met meerdere lange signalen om voorrang af te dwingen."], "correct": [0], "feedback": "Korte, duidelijke signalen kunnen kruisend verkeer waarschuwen. Het signaal vervangt zicht, snelheid minderen en stoppen zo nodig niet. Volg altijd het plaatselijke verkeersplan en de daar afgesproken signalen."},
  {"id": "V14", "prompt": "Wie levert bij gedeeld intern verkeer een bijdrage aan veilig werken?", "options": ["Alleen de werkgever, via het verkeersplan.", "Alleen de voetgangers, omdat zij de looproute kiezen.", "Werkgever, bestuurders en andere aanwezigen, ieder vanuit hun eigen rol.", "Alleen bestuurders, omdat zij met de trucks rijden."], "correct": [2], "feedback": "De werkgever organiseert veilig verkeer en geeft instructies. Bestuurders en werknemers volgen de afspraken en melden gevaren. Ook bezoekers moeten zich houden aan de lokale regels. De wettelijke plichten verschillen per rol.", "image": "traffic", "alt": "Gemarkeerde looproute in een bedrijfshal"},
  {"id": "V15", "prompt": "Wat vind je in een arbocatalogus voor een sector met intern transport?", "options": ["Een vervanging van de Arbeidsomstandighedenwet voor die sector.", "Praktische maatregelen en afspraken om aan de wettelijke doelen te voldoen.", "Een openbaar register met alle heftruckcertificaten van de sector.", "Het onderhoudsboek van één type heftruck."], "correct": [1], "feedback": "Werkgevers en werknemers kunnen in een arbocatalogus praktische oplossingen vastleggen voor de arbeidsrisico’s in hun sector. Denk aan de inrichting van looproutes bij intern transport. De arbocatalogus geeft invulling aan doelvoorschriften uit de arbowetgeving."},
  {"id": "V16", "prompt": "Een pallet staat vlak tegen een wand. Wanneer kan gecontroleerd opnemen in twee stappen volgens de werkinstructie nodig zijn?", "options": ["Wanneer je de vorkopeningen niet ziet en de vorken op goed geluk kunt insteken.", "Wanneer de vorken achter de pallet zouden uitsteken en je hem daardoor niet meteen tot de hiel kunt opnemen.", "Wanneer de vorken te kort zijn om de last voldoende te ondersteunen.", "Wanneer de last zwaarder is dan de toegestane capaciteit."], "correct": [1], "feedback": "De bron noemt dit undercutting. Bij lange vorken kan direct volledig insteken een wand of achterliggende last raken. Gebruik bij voorkeur passende vorken. Neem alleen in twee stappen op als de werkinstructie dat toestaat, de ondersteuning in elke stap voldoende is en de grotere lastzwaartepuntafstand binnen het lastdiagram blijft.", "image": "pallet", "alt": "Houten pallet met vorkopeningen"},
  {"id": "V17", "prompt": "Hoe stel je de vorken in voor een metalen transportrek waarvan de gemarkeerde vorkopnames verschillende breedtes toelaten?", "options": ["Zo breed als de opnamepunten toelaten, met gelijkmatige steun links en rechts.", "Zo dat één vork meer gewicht draagt dan de andere.", "Zo smal mogelijk zodat je sneller kunt insteken.", "Beide vorken zo dicht mogelijk naast elkaar onder het midden."], "correct": [0], "feedback": "Kies de daarvoor bedoelde opnamepunten en zorg voor stabiele steun op beide vorken. Een passende brede spreiding verkleint de kans op zijwaarts schuiven of kantelen. De uitvoering en borging moeten passen bij het transportrek."},
  {"id": "R01", "prompt": "Je nadert een stapel recht van voren. Welke volgorde is veilig om de vorken op opname- of afzethoogte te brengen?", "options": ["Blijf langzaam naar de stapel rijden terwijl je de vorken heft.", "Stop vlak voor de stapel, beveilig de truck tegen rijden en stel de vorken op hoogte en neiging in.", "Hef de vorken een meter vóór de stapel en rijd meteen door met hoge vorken.", "Stop vlak voor de stapel en steek de vorken maximaal achterover in de openingen."], "correct": [1], "feedback": "Voer de hoogteverstelling uit vanuit stilstand. Gebruik parkeerrem en neutraal waar de truckinstructie dat voorschrijft. De ABA-oefenmethode noemt ongeveer 15 cm als maximale stopafstand voor de oefenopstelling. Volg voor je werk de procedure en omstandigheden op locatie.", "image": "rack", "alt": "Heftruck naast een magazijnstelling"},
  {"id": "R02", "prompt": "Bij het verlaten van een verpakkingslijn ontneemt een hoge kist je het zicht vooruit. De vlakke route achter de truck is vrij en achteruitrijden is er toegestaan. Hoe vervolg je de rit?", "options": ["Bekijk de route één keer vanaf de grond en rijd daarna vooruit met de claxon aan.", "Rijd beheerst achteruit en blijf kijken in de rijrichting.", "Rijd vooruit en gebruik alleen de aanwijzingen van iemand achter je.", "Rijd langzaam vooruit met je hoofd buiten de beschermconstructie."], "correct": [1], "feedback": "Je moet de route in de rijrichting kunnen blijven overzien. In deze situatie kan dat door beheerst achteruit te rijden. Als ook dat geen veilig zicht geeft, stop je en volg je de lokale procedure. Voor hellingen gelden aparte regels voor de positie van de last."},
  {"id": "R03", "prompt": "Je zet de heftruck aan het einde van de dienst in het parkeervak. In welke stand laat je de lege vorken achter?", "options": ["Met de hielen op de vloer en de punten duidelijk omhoog.", "Met de punten op de vloer en de hielen op normale transporthoogte.", "Volledig omlaag, met de vorkpunten op de vloer zoals voorgeschreven voor deze truck.", "Met beide vorken op transporthoogte en horizontaal."], "correct": [2], "feedback": "Vorken op de vloer beperken struikel- en aanrijgevaar en voorkomen dat het hefmechanisme onnodig hoog blijft staan. Zet de truck vervolgens veilig stil volgens de instructie, met onder meer de parkeerrem en de rijrichting in neutraal waar van toepassing.", "image": "parked", "alt": "Heftruck op een vlakke ondergrond"},
  {"id": "R04", "prompt": "Je vervoert een pallet met een heftruck met neigbare mast. Hoe bepaal je de achterwaartse neiging?", "options": ["Gebruik volgens de instructie voldoende neiging voor de last en de rijomstandigheden.", "Gebruik altijd de maximale neiging, ongeacht de last.", "Kantel bij elk type last precies evenveel achterover.", "Houd de vorken altijd horizontaal zoals bij het afzetten."], "correct": [0], "feedback": "De transportstand moet de last stabiel ondersteunen. De benodigde neiging hangt af van truck, lading en ondergrond. Houd de last laag en gebruik de voorgeschreven stand. Maximaal achterover neigen is geen standaardinstelling voor elke last."},
  {"id": "R05", "prompt": "Je begint vanaf de grond met het laden van een open vrachtwagen. Welke afspraak en controle horen bij het veilig starten?", "options": ["De chauffeur heeft alleen het gewicht op de vrachtbrief gecontroleerd.", "De chauffeur heeft de bandenspanning doorgegeven en mag daarna vertrekken.", "De bestemming is bekend en de chauffeur blijft in het laadgebied staan.", "De chauffeur weet dat het laden begint en staat veilig. Het voertuig is volgens de locatieprocedure tegen beweging geborgd."], "correct": [3], "feedback": "Stem de laadprocedure af vóór je begint. De chauffeur wacht op de aangewezen veilige plek. Controleer de parkeerrem en de vereiste borging, bijvoorbeeld wielkeggen of een ander borgsysteem. De motor staat uit als de locatieprocedure dit voorschrijft.", "image": "dock", "alt": "Laadplek met een vrachtwagen aan het dock"},
  {"id": "R06", "prompt": "Je moet een lage drempel of goot kruisen op een goedgekeurde rijroute. Hoe doe je dat beheerst?", "options": ["Rijd sneller zodat de truck minder lang op de drempel staat.", "Rijd altijd achteruit, onafhankelijk van route of obstakel.", "Rijd langzaam en neem zo nodig een schuine lijn als die voor deze truck en route is toegestaan.", "Rijd altijd in dezelfde lijn en houd de snelheid gelijk."], "correct": [2], "feedback": "Een lage snelheid beperkt schokken en gewichtsverplaatsing. Bij sommige lage obstakels kan gecontroleerd schuin passeren helpen, mits de truckinstructie, markering en de beschikbare ruimte dit toelaten. Bij rails of andere vaste kruisingen volg je de voorgeschreven oversteekroute."},
  {"id": "R07", "prompt": "Een helling is geschikt voor de beladen heftruck. Waar bevindt de last zich als je recht omhoog rijdt?", "options": ["Aan de lage zijde van de helling.", "Aan de hoge zijde van de helling, dus vóór de truck in deze rijrichting.", "Aan de lage zijde, met de mast voorover.", "Zijwaarts ten opzichte van de helling."], "correct": [1], "feedback": "Bij een beladen heftruck blijft de last aan de hoge kant van de helling. Omhoog betekent dat in deze situatie vooruitrijden. Houd de last laag, houd genoeg bodemvrijheid en volg de grenzen en instructies van de fabrikant.", "image": "ramp", "alt": "Heftruck bij een rijplaat"},
  {"id": "R08", "prompt": "Bij deze lege contragewichtheftruck moeten de vorken op een toegestane helling naar beneden wijzen. Wat is het doel?", "options": ["De stabiliteit en grip tijdens het rijden ondersteunen.", "Het zicht verbeteren door de vorken hoger te kunnen zetten.", "Sneller kunnen rijden met minder bandenslijtage.", "De rijtijd in beide richtingen gelijk houden."], "correct": [0], "feedback": "De voorgeschreven oriëntatie past bij de gewichtsverdeling van een lege contragewichtheftruck. Daardoor blijven stabiliteit en grip beter beheersbaar. Dit is een andere situatie dan rijden met een last. Gebruik de hellinginstructie voor het specifieke type truck."},
  {"id": "R09", "prompt": "Je neigt de mast voorover terwijl een zware last hoog geheven is. Wat verklaart het toenemende gevaar op voorover kantelen?", "options": ["De zijwaartse kracht op de achteras wordt altijd groter dan de voorwaartse kracht.", "Het gemeten gewicht van de last neemt toe doordat de mast beweegt.", "Het gezamenlijke zwaartepunt van truck en last verplaatst zich naar voren.", "De vooras verplaatst zich naar achteren ten opzichte van het chassis."], "correct": [2], "feedback": "Bij voorover neigen beweegt de last verder naar voren. Daardoor verplaatst ook het gezamenlijke zwaartepunt zich richting de voorwaartse kantelgrens. Neig op hoogte alleen beperkt en waar dat voor het gecontroleerd afzetten is voorgeschreven.", "image": "tip", "alt": "Schematische heftruck met een hooggeheven last"},
  {"id": "R10", "prompt": "Een buiten opgeslagen pallet is met sneeuw en ijs bedekt. Welk effect is belangrijk bij de capaciteitscontrole?", "options": ["De toegestane hefcapaciteit van de truck wordt hoger.", "De totale massa op de vorken blijft gelijk.", "Het totale gewicht op de vorken kan toenemen.", "De pallet kan door het ijs alleen maar meer grip op de vorken krijgen."], "correct": [2], "feedback": "Sneeuw en ijs die je mee optilt, tellen mee bij het gewicht. Bovendien kan ijs de grip op de vorken verminderen. Controleer het werkelijke gewicht en de stabiliteit van de last voordat je deze verplaatst."},
  {"id": "R11", "prompt": "Er ligt los verpakkingshout op je rijroute. Je kunt het volgens de bedrijfsinstructie veilig opruimen. Wat doe je?", "options": ["Rijd erlangs en meld het bij de volgende pauze.", "Zet de truck veilig weg en maak de route vrij als dat veilig kan.", "Rijd er langzaam overheen en waarschuw de volgende bestuurder.", "Duw het hout met de vorken naar de rand van de looproute."], "correct": [1], "feedback": "Een los stuk hout kan onder een wiel komen en de truck of last laten schokken. Zet de truck veilig stil voordat je uitstapt en ruim het obstakel alleen op als dit veilig kan. Beveilig en meld de situatie als je de route niet zelf vrij kunt maken.", "image": "warehouse", "alt": "Magazijngangen met rijmarkering"},
  {"id": "R12", "prompt": "Volgens de fabrikant en de locatie-instructie mag je met deze beladen reachtruck over de helling rijden. Welke stand past bij deze rit?", "options": ["De last wijst naar boven en wordt naar voren geneigd.", "De last wijst naar beneden en wordt naar voren geneigd.", "De last wijst naar boven, met de reachfunctie ingetrokken en de voorgeschreven achterwaartse neiging.", "De last wijst naar boven met de reachfunctie volledig uitgeschoven."], "correct": [2], "feedback": "Veel reachtrucks zijn bedoeld voor vlakke vloeren. Gebruik een helling alleen als het model en de locatie dit toestaan. In deze situatie blijft de last aan de hoge kant en ingetrokken in de voorgeschreven lage transportstand."},
  {"id": "R13", "prompt": "Bij een stapeloefening stop je dicht bij de stapel voordat je heft. Waar is die korte stopafstand vooral voor bedoeld?", "options": ["De vorken nauwkeurig positioneren en de ruimte vóór de truck beperken.", "Tijd winnen door de vorken onderweg al op te tillen.", "De parkeerrem zo min mogelijk gebruiken.", "Een doorgang tussen truck en stapel vrijlaten voor voetgangers."], "correct": [0], "feedback": "Het helpt om de vorken vanuit stilstand nauwkeurig uit te lijnen. Zo blijft ook minder ruimte over waar iemand de gevarenzone in kan lopen. Dit is geen afscherming. Stop het werk zodra iemand de werkzone betreedt.", "image": "rack", "alt": "Heftruck naast een magazijnstelling"},
  {"id": "R14", "prompt": "De rijinstructie voor dit oefenmagazijn gebruikt de ABA-vuistregel voor twee heftrucks achter elkaar. Wat is de richtafstand bij normale omstandigheden?", "options": ["Eén trucklengte.", "Twee trucklengten.", "Drie trucklengten.", "Vier trucklengten."], "correct": [2], "feedback": "De bron gebruikt ongeveer drie trucklengten als vuistregel. Je moet altijd binnen de vrije afstand kunnen stoppen. Houd meer afstand bij natte vloeren, hoge massa, beperkt zicht of wanneer de lokale instructie dat vraagt."},
  {"id": "R15", "prompt": "Tijdens de rit merk je dat de bedrijfsrem veel zwakker reageert dan normaal. Wat doe je als eerste?", "options": ["Rijd naar de leidinggevende om het meteen te melden.", "Breng de truck zo snel als veilig mogelijk tot stilstand, beveilig hem en roep hulp in.", "Rijd langzamer door tot het volgende geplande onderhoud.", "Maak de taak af als de parkeerrem nog werkt."], "correct": [1], "feedback": "Een afwijkende remwerking kan direct tot verlies van controle leiden. Stop beheerst op de eerst veilige plek die je kunt bereiken, voorkom verder gebruik en meld de storing. De parkeerrem vervangt de bedrijfsrem niet voor normaal rijden.", "image": "inspection", "alt": "Detail van een heftruckwiel"},
  {"id": "R16", "prompt": "Een houten pallet heeft een zware machine aan één zijde. De last is geschikt om te heffen. Hoe kies je de stand van de vorken?", "options": ["Gebruik ongeacht de last de maximale spreiding van het vorkenbord.", "Kies binnen de toegestane opnamepunten een stand die de last stabiel over beide vorken verdeelt.", "Zet de vorken altijd dicht bij elkaar voor snel insteken.", "Plaats beide vorken zo dicht mogelijk bij het middenblok."], "correct": [1], "feedback": "Laat beide vorken de last zo gelijkmatig mogelijk dragen en gebruik de daarvoor bestemde openingen. Een ongelijk verdeelde last vraagt controle van het zwaartepunt en de capaciteit. Stop als de last niet veilig op beide vorken kan worden ondersteund."},
  {"id": "R17", "prompt": "Welke instelling gebruik je bij een stilstaande heftruck met een aparte parkeerrem en rijrichtingkiezer voordat je een pallet op hoogte zet?", "options": ["Parkeerrem aan en de rijrichting vooruit geselecteerd.", "Parkeerrem aan en de rijrichting in neutraal.", "Parkeerrem los en de rijrichting achteruit geselecteerd.", "Alleen neutraal, zonder de truck tegen rijden te beveiligen."], "correct": [1], "feedback": "Met parkeerrem en neutraal voorkom je onbedoelde rijbewegingen tijdens de bediening van de hydrauliek. Volg bij modellen met automatische beveiliging de instructies voor dat systeem. Controleer vóór de volgende rijbeweging weer je omgeving.", "image": "controls", "alt": "Bedieningsplek in een heftruck"},
  {"id": "R18", "prompt": "Een voorzetstuk plaatst dezelfde last verder naar voren. Wat verwacht je van het toegestane hefvermogen bij dezelfde hefhoogte?", "options": ["Het hefvermogen blijft altijd gelijk.", "Het hefvermogen wordt groter.", "Het hefvermogen blijft gelijk als de inhoud van de last kan bewegen.", "Het toegestane hefvermogen kan lager worden."], "correct": [3], "feedback": "De grotere lastzwaartepuntafstand vergroot het moment van de last. Het voorzetstuk kan ook eigen gewicht toevoegen. Gebruik daarom het lastdiagram voor de combinatie van truck en voorzetstuk om de restcapaciteit te bepalen."},
  {"id": "R19", "prompt": "Je moet onder een lage doorgang een pallet iets opheffen terwijl de totale masthoogte gelijk blijft. Welke maat op de truckspecificatie vertelt hoeveel ruimte je daarvoor hebt?", "options": ["De vrije hefhoogte, het bereik waarin de vorken stijgen zonder dat de mast uitschuift.", "De maximale vorkspreiding, de grootste afstand tussen de vorken.", "De maximale hefhoogte, gemeten bij volledig uitgeschoven mast.", "De doorrijhoogte, gemeten vanaf de vloer tot het hoogste vaste punt in de laagste stand."], "correct": [0], "feedback": "Binnen de vrije hefhoogte stijgen de vorken terwijl de mast niet verder uitschuift. Die maat is belangrijk onder lage plafonds of in een trailer. Controleer ook of het lastrek, de last en andere delen binnen de beschikbare ruimte blijven.", "image": "mast", "alt": "Zijaanzicht van een hefmast"},
  {"id": "R20", "prompt": "Je truck staat veilig op de parkeerrem. Bij dit model kies je de rijrichting terwijl de rem nog vaststaat. Welke volgorde geeft vlak vóór vertrek de beste controle?", "options": ["Kies de rijrichting, kijk rondom en in de rijrichting, los de parkeerrem en vertrek rustig zodra het vrij is.", "Kies de rijrichting, los de parkeerrem en kijk pas tijdens het optrekken rondom.", "Los de parkeerrem, laat de truck rollen en kies onderweg de rijrichting.", "Kijk één keer over je schouder, stel daarna alles in en rijd weg zonder opnieuw te kijken."], "correct": [0], "feedback": "Bij deze bedieningsvolgorde blijft de truck stilstaan terwijl je de rijrichting kiest en de omgeving controleert. Let op voetgangers, andere voertuigen en de uitzwaai. Als er na de laatste controle tijd verstrijkt, kijk je opnieuw vóór je vertrekt."},
  {"id": "R21", "prompt": "Welke stand past bij de ABA-oefenmethode voor het vervoeren van een stabiele palletlast op een vlakke vloer?", "options": ["De vorkpunten bijna op de vloer en de mast rechtop.", "De vorken laag, in deze oefenmethode ongeveer 10–15 cm boven de vloer, met voldoende achterwaartse neiging.", "De vorken ongeveer 10–15 cm boven de vloer met altijd maximale achterwaartse neiging.", "De vorken ongeveer 10–15 cm boven de vloer met de mast voorover."], "correct": [1], "feedback": "De last blijft bij een lage transportstand dichter bij de vloer en heeft minder invloed op de stabiliteit. Voldoende achterwaartse neiging helpt de last op haar plek te houden. De 10–15 cm geldt voor deze oefenmethode. Volg de transportstand die voor jouw truck, last en rijroute is voorgeschreven.", "image": "truck", "alt": "Contragewichtheftruck met mast en vorken"}
];
